import fs from 'node:fs/promises';
import path from 'node:path';
import { DeleteObjectCommand, GetObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';
import type { AppConfig } from '../../config/env.js';

/**
 * Where project files live. Keys are generated by the server (`ws/<workspace>/p/<project>/<file id>`), never taken
 * from a client, so they cannot point outside the workspace's prefix.
 */
export interface Storage {
  readonly driver: 's3' | 'local';
  put(key: string, body: Buffer, mime: string): Promise<void>;
  get(key: string): Promise<Buffer>;
  delete(key: string): Promise<void>;
  /** A short-lived URL the browser can download from directly, or null when the API must stream the file itself. */
  signedDownloadUrl(key: string, opts: { filename: string; mime: string; expiresIn: number }): Promise<string | null>;
}

const KEY = /^[A-Za-z0-9_\-/]{1,300}$/;
export function assertKey(key: string): void {
  if (!KEY.test(key) || key.includes('..') || key.startsWith('/')) throw new Error('invalid storage key');
}

/** RFC 6266 attachment header that survives any file name (ASCII fallback + UTF-8 form). */
export function attachmentHeader(filename: string): string {
  const ascii = filename.replace(/[^\x20-\x7e]/g, '_').replace(/["\\]/g, '_');
  return `attachment; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(filename)}`;
}

/** Types the browser may be told about; everything else downloads as a generic binary. */
const SAFE_TYPES = new Set(['application/pdf', 'text/plain', 'text/csv', 'text/markdown', 'application/json', 'image/png', 'image/jpeg', 'image/gif', 'image/webp']);
export const downloadType = (mime: string) => (SAFE_TYPES.has(mime) ? mime : 'application/octet-stream');

export function createLocalStorage(dir: string): Storage {
  const root = path.resolve(dir);
  const full = (key: string) => {
    assertKey(key);
    const p = path.resolve(root, key);
    if (!p.startsWith(root + path.sep)) throw new Error('invalid storage key');
    return p;
  };
  return {
    driver: 'local',
    async put(key, body) {
      const p = full(key);
      await fs.mkdir(path.dirname(p), { recursive: true });
      await fs.writeFile(p, body);
    },
    get: key => fs.readFile(full(key)),
    async delete(key) { await fs.rm(full(key), { force: true }); },
    async signedDownloadUrl() { return null; }
  };
}

export function createS3Storage(s3: NonNullable<AppConfig['storage']['s3']>): Storage {
  const client = new S3Client({
    region: s3.region, endpoint: s3.endpoint, forcePathStyle: s3.forcePathStyle,
    credentials: { accessKeyId: s3.accessKeyId, secretAccessKey: s3.secretAccessKey }
  });
  return {
    driver: 's3',
    async put(key, body, mime) {
      assertKey(key);
      await client.send(new PutObjectCommand({ Bucket: s3.bucket, Key: key, Body: body, ContentType: mime, ContentLength: body.length }));
    },
    async get(key) {
      assertKey(key);
      const r = await client.send(new GetObjectCommand({ Bucket: s3.bucket, Key: key }));
      return Buffer.from(await r.Body!.transformToByteArray());
    },
    async delete(key) {
      assertKey(key);
      await client.send(new DeleteObjectCommand({ Bucket: s3.bucket, Key: key }));
    },
    signedDownloadUrl(key, { filename, mime, expiresIn }) {
      assertKey(key);
      return getSignedUrl(client, new GetObjectCommand({
        Bucket: s3.bucket, Key: key, ResponseContentDisposition: attachmentHeader(filename), ResponseContentType: downloadType(mime)
      }), { expiresIn });
    }
  };
}

export function createStorage(cfg: AppConfig): Storage | null {
  if (cfg.storage.driver === 's3') return createS3Storage(cfg.storage.s3!);
  if (cfg.storage.driver === 'local') return createLocalStorage(cfg.storage.dir!);
  return null;
}
